import React, { useState, useEffect } from "react";
import Calendar from "react-calendar";
import "react-calendar/dist/Calendar.css";
import axios from "axios";
import "../Calendar.css"; // 스타일은 필요에 맞게 추가하세요

function CalendarPage() {
  const [selectedDate, setSelectedDate] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [reviewText, setReviewText] = useState("");
  const [diary, setDiary] = useState({}); // { '2025-07-29': { title, poster, review } }

  const handleDateClick = (date) => {
    setSelectedDate(date);
    setIsModalOpen(true);
    setSearchQuery("");
    setSearchResults([]);
    setSelectedMovie(null);
    setReviewText("");
  };

  const handleSearch = async () => {
    try {
      const response = await axios.get(
        `https://api.themoviedb.org/3/search/movie`,
        {
          params: {
            api_key: "YOUR_TMDB_API_KEY", // TMDB API 키 입력
            query: searchQuery,
          },
        }
      );
      setSearchResults(response.data.results);
    } catch (error) {
      console.error("영화 검색 오류:", error);
    }
  };

  const handleSave = () => {
    if (!selectedMovie || !reviewText) return;
    const dateKey = selectedDate.toISOString().split("T")[0];
    setDiary((prev) => ({
      ...prev,
      [dateKey]: {
        title: selectedMovie.title,
        poster: selectedMovie.poster_path,
        review: reviewText,
      },
    }));
    setIsModalOpen(false);
  };

  const renderTileContent = ({ date }) => {
    const dateKey = date.toISOString().split("T")[0];
    const record = diary[dateKey];
    if (record) {
      return (
        <div className="diary-thumbnail">
          <img
            src={`https://image.tmdb.org/t/p/w200${record.poster}`}
            alt={record.title}
            className="thumb-img"
          />
        </div>
      );
    }
    return null;
  };

  return (
    <div className="calendar-page">
      <h2>🎬 나의 영화 리뷰 달력</h2>
      <Calendar onClickDay={handleDateClick} tileContent={renderTileContent} />

      {isModalOpen && (
        <div className="modal-overlay">
          <div className="modal-box">
            <h3>{selectedDate.toDateString()} 영화 등록</h3>

            {!selectedMovie ? (
              <>
                <input
                  type="text"
                  placeholder="영화 제목 검색"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
                <button onClick={handleSearch}>검색</button>
                <div className="search-results">
                  {searchResults.map((movie) => (
                    <div
                      key={movie.id}
                      className="search-result"
                      onClick={() => setSelectedMovie(movie)}
                    >
                      <img
                        src={`https://image.tmdb.org/t/p/w200${movie.poster_path}`}
                        alt={movie.title}
                      />
                      <p>{movie.title}</p>
                    </div>
                  ))}
                </div>
              </>
            ) : (
              <>
                <div className="selected-movie">
                  <img
                    src={`https://image.tmdb.org/t/p/w200${selectedMovie.poster_path}`}
                    alt={selectedMovie.title}
                  />
                  <h4>{selectedMovie.title}</h4>
                </div>
                <textarea
                  placeholder="리뷰 작성"
                  value={reviewText}
                  onChange={(e) => setReviewText(e.target.value)}
                />
                <button onClick={handleSave}>저장</button>
              </>
            )}

            <button onClick={() => setIsModalOpen(false)}>닫기</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default CalendarPage;
